import{b as t,O as e,g as a,j as i}from"./chunks/framework.DcaUmd3X.js";const k=JSON.parse('{"title":"测试报告","description":"","frontmatter":{},"headers":[],"relativePath":"automation/pytest/advanced/test-report/index.md","filePath":"自动化测试/2.pytest+requests/5.进阶篇/28.测试报告.md","lastUpdated":1786983642000}'),n={name:"automation/pytest/advanced/test-report/index.md"};function o(d,s,l,p,c,r){return e(),a("div",null,[...s[0]||(s[0]=[i(`<h1 id="测试报告" tabindex="-1">测试报告 <a class="header-anchor" href="#测试报告" aria-label="Permalink to &quot;测试报告&quot;">​</a></h1><blockquote><p>测试跑完了，结果怎么呈现给团队、怎么进 CI、怎么定位最慢的用例？这一章讲 pytest 的输出控制、机器可读的 XML 报告、漂亮的 HTML 报告，以及如何从报告里挖出「哪个测试最慢」。</p></blockquote><h2 id="控制台输出-先会调「看得清」" tabindex="-1">控制台输出：先会调「看得清」 <a class="header-anchor" href="#控制台输出-先会调「看得清」" aria-label="Permalink to &quot;控制台输出：先会调「看得清」&quot;">​</a></h2><p>几个控制输出的核心参数（第 3 章提过，这里串起来）：</p><table tabindex="0"><thead><tr><th>参数</th><th>作用</th></tr></thead><tbody><tr><td><code>-v</code> / <code>-q</code></td><td>详细 / 安静模式</td></tr><tr><td><code>-s</code></td><td>不吞 print 输出</td></tr><tr><td><code>--tb=style</code></td><td>回溯样式：<code>short</code>/<code>long</code>/<code>line</code>/<code>native</code>/<code>no</code></td></tr><tr><td><code>-r</code></td><td>显示额外摘要（<code>-rA</code> 显示所有结果，含 skip/xfail）</td></tr><tr><td><code>-l</code> / <code>--showlocals</code></td><td>失败时显示局部变量</td></tr><tr><td><code>--durations=N</code></td><td>显示最慢的 N 个测试</td></tr></tbody></table><p>调试失败时最有用的是 <code>--tb=short -l</code>：短回溯 + 失败处局部变量，一眼定位问题。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pytest</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --tb=short</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -l</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # 失败显示：短回溯 + 局部变量</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pytest</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rA</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                    # 结束后显示 skip/xfail 的摘要和原因</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pytest</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --durations=10</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">         # 报告最慢的 10 个测试</span></span></code></pre></div><h2 id="xml-报告-给-ci-用" tabindex="-1">XML 报告：给 CI 用 <a class="header-anchor" href="#xml-报告-给-ci-用" aria-label="Permalink to &quot;XML 报告：给 CI 用&quot;">​</a></h2><p><code>--junitxml</code> 生成 JUnit 格式的 XML，几乎所有 CI（Jenkins、GitLab CI、GitHub Actions）都能解析：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pytest</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --junitxml=reports/report.xml</span></span></code></pre></div><p>生成的 <code>report.xml</code> 每个测试一行，带 <code>classname</code>/<code>name</code>/<code>time</code>/<code>failure</code> 等信息，CI 拿来画测试结果图表、发失败通知。</p><blockquote><p><strong>要点：XML 是「机器读的报告」，给 CI 和自动化流水线；它不追求好看，追求结构化、可解析。人要看漂亮报告，用下面的 HTML。</strong></p></blockquote><h2 id="html-报告-给人看" tabindex="-1">HTML 报告：给人看 <a class="header-anchor" href="#html-报告-给人看" aria-label="Permalink to &quot;HTML 报告：给人看&quot;">​</a></h2><p><code>pytest-html</code> 插件生成漂亮的 HTML 报告，适合发到群里、邮件里给人看：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pytest-html</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pytest</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --html=reports/report.html</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --self-contained-html</span></span></code></pre></div><p><code>--self-contained-html</code> 把 CSS/JS 内嵌进一个文件，方便直接分享单个 HTML（不用带资源文件夹）。报告里有每个用例的通过/失败状态、失败回溯、耗时，还能按状态筛选。</p><h2 id="从报告挖性能-找最慢测试" tabindex="-1">从报告挖性能：找最慢测试 <a class="header-anchor" href="#从报告挖性能-找最慢测试" aria-label="Permalink to &quot;从报告挖性能：找最慢测试&quot;">​</a></h2><p>接口测试套件越跑越慢，问题往往出在少数几个慢测试。<code>--durations</code> 精确指出凶手：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pytest</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --durations=10</span></span></code></pre></div><p>输出类似：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>============ slowest 10 durations ============</span></span>
<span class="line"><span>12.30s call     test_export_all_orders</span></span>
<span class="line"><span>8.20s  call     test_generate_report</span></span>
<span class="line"><span>1.50s  call     test_list_products</span></span>
<span class="line"><span>...</span></span></code></pre></div><p>找到慢测试后，通常这几招：</p><ol><li><strong>标记 + 排除</strong>：<code>@pytest.mark.slow</code>，日常跑 <code>-m &quot;not slow&quot;</code>，慢测试只在完整跑时执行</li><li><strong>减少重复请求</strong>：session 级 fixture 复用登录态（第 21 章），别每个测试都登录</li><li><strong>并行</strong>：用 pytest-xdist 并行跑（下一章）</li></ol><h2 id="失败报告的黄金信息" tabindex="-1">失败报告的黄金信息 <a class="header-anchor" href="#失败报告的黄金信息" aria-label="Permalink to &quot;失败报告的黄金信息&quot;">​</a></h2><p>一个失败的测试，报告里藏着定位所需的全部信息：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&gt;       assert resp.status_code == 200</span></span>
<span class="line"><span>E       assert 403 == 200</span></span>
<span class="line"><span>E        +  where 403 = &lt;Response [403]&gt;.status_code</span></span>
<span class="line"><span></span></span>
<span class="line"><span>test_products.py:42: AssertionError</span></span></code></pre></div><ul><li><strong>断言对比</strong>：<code>403 == 200</code>，左边是实际、右边是期望</li><li><strong>来源追踪</strong>：<code>&lt;Response [403]&gt;.status_code</code> 告诉你 403 来自哪</li><li><strong>文件行号</strong>：<code>test_products.py:42</code> 精确到出错行</li></ul><p>配合 <code>-l</code> 显示局部变量（比如 <code>resp.text</code> 里就有服务端返回的错误详情），不用加 print 就能看到上下文。</p><h2 id="本章小结" tabindex="-1">本章小结 <a class="header-anchor" href="#本章小结" aria-label="Permalink to &quot;本章小结&quot;">​</a></h2><ul><li>控制台参数：<code>-v</code>/<code>-q</code>/<code>-s</code>/<code>--tb</code>/<code>-r</code>/<code>-l</code>/<code>--durations</code>，调试用 <code>--tb=short -l</code></li><li><code>--junitxml</code>：机器可读的 XML，给 CI 流水线</li><li><code>pytest-html</code>：漂亮的 HTML 报告，<code>--self-contained-html</code> 内嵌资源方便分享</li><li><code>--durations=N</code> 找出最慢测试，配合 marker 排除、session 级复用、并行来提速</li><li>失败报告三要素：断言对比、来源追踪、文件行号；<code>-l</code> 看局部变量</li></ul>`,30)])])}const u=t(n,[["render",o]]);export{k as __pageData,u as default};
